from pathlib import Path
p=Path('dashboard.html');s=p.read_text(encoding='utf-8');M='WINTURBO_LOGGED_IN_USER_V48'
if M in s: raise SystemExit(0)
css='''<style>/* WINTURBO_LOGGED_IN_USER_V48 */\n#loggedInUserV48{position:fixed;top:12px;right:18px;z-index:9998;display:none;align-items:center;gap:9px;padding:8px 12px;border:1px solid var(--line);border-radius:999px;background:rgba(10,16,12,.94);box-shadow:0 6px 24px rgba(0,0,0,.25);font-size:11px;backdrop-filter:blur(10px)}#loggedInUserV48 .dot{width:7px;height:7px;border-radius:50%;background:#67ff8b}#loggedInUserV48 b{font-size:12px}#loggedInUserV48 .role{color:var(--muted);text-transform:uppercase}@media(max-width:700px){#loggedInUserV48{top:8px;right:8px;max-width:72vw}#loggedInUserV48 b{max-width:42vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}\n</style>'''
js=r'''<div id="loggedInUserV48"><span class="dot"></span><span>Logged in as</span><b id="loggedInEmailV48">—</b><span class="role" id="loggedInRoleV48"></span></div><script>(function(){async function show(){const box=document.getElementById('loggedInUserV48');if(!box)return;const r=await sb.auth.getUser(),u=r.data?.user;if(!u){box.style.display='none';return}document.getElementById('loggedInEmailV48').textContent=u.email||'Signed-in user';let role='';const g=await sb.from('user_access_grants').select('access_level').eq('user_id',u.id).maybeSingle();role=g.data?.access_level==='admin'?'Admin':g.data?.access_level==='section'?'Section Access':g.data?.access_level==='view'?'View Only':'';document.getElementById('loggedInRoleV48').textContent=role?`· ${role}`:'';box.style.display='flex'}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(show,400),{once:true});else setTimeout(show,400);sb.auth.onAuthStateChange(()=>setTimeout(show,100))})();</script>'''
s=s.replace('</head>',css+'\n</head>',1).replace('</body>',js+'\n</body>',1);p.write_text(s,encoding='utf-8')